shots.draw_js:
clearScene();setBig(null);
setEq("$$\\Delta w=\\alpha\\big(r+\\gamma\\,x(s')^{\\top}w-x(s)^{\\top}w\\big)x(s)$$","top");
note("目标里也有 w",640,310,"r lg");
setCap("TD 的标签<b>依赖于你正在优化的参数</b>。监督学习里没有这种事。");

clearScene();setEq(null);
setBig("它在最小化某个损失","毕竟长得就是梯度下降的样子");
setCap("形式上一模一样 —— 但<b>它不是任何函数的梯度</b>。");

clearScene();setBig(null);
setEq("$$\\nabla_w\\big(r+\\gamma x(s')^{\\top}w-x(s)^{\\top}w\\big)^2 \\;=\\; 2\\delta\\big(\\gamma x(s')-x(s)\\big)$$","top");
note("真梯度含 γx(s′)",640,300,"y lg");
note("TD 把它丢掉了",640,360,"r lg");
setCap("真正求导会带出 <b>γx(s′)</b> 这一项。TD 把它<b>扔了</b>，只留 −x(s)。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"MC 的填法",sub:"标签不含 w · 真梯度",state:"on"},
  {label:"TD 的填法",sub:"标签含 w · 半梯度",state:"dead"},
  {label:"残差梯度",sub:"真梯度但慢",state:"off"}]});
note("只有 MC 是真的梯度下降",640,420,"y");
setCap
("三个填法里，<b>只有 MC 的标签不含 w</b>，所以只有它是真梯度下降。");

clearScene();setBig(null);setEq(null);
note("不动点 ≠ 极小点",640,290,"r lg");
note("所以没有下降保证",640,360,"r lg");
setCap("<b>指名反驳</b>：它不是任何函数的梯度，所以<b>没有「每步都在变好」这回事</b>。");

clearScene();setBig(null);
setEq("$$x(s_i)=2e_i+e_8\\ (i\\le 6),\\qquad x(s_7)=e_7+2e_8$$","top");
note("7 状态 · 8 维特征",640,300,"b lg");
note("奖励全 0，真值 V ≡ 0",640,360,"g lg");
setCap("Baird 的反例：<b>正确答案是把所有 V̂ 压到 0</b>，没有比这更简单的目标。");

clearScene();setEq(null);
setBig("那是特征没选好","或者步长开太大了");
setCap("两个都不是。<b>同一组特征、同一个步长</b>，换个数据来源就不发散了。");

clearScene();setBig(null);
setEq("$$w=\\mathbf{1}:\\quad \\hat V(s_1)=2+1=3,\\quad \\hat V(s_7)=1+2=3$$","top");
note("这两个数她说了",640,300,"y lg");
note("用来反推特征索引",640,360,"sm lg");
setCap("验证重建：w 取全 1 时两个值都是 <b>3</b> —— 与她课上说的一致。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:800,vals:[2.62,17.42],x:380,y:430,w:520,h:170,max:20,
  label:function(i){return ["在策略 k=100","离策略 k=100"][i];},
  cls:function(i){return i===0?"g":"r";},
  fmt:function(v){return v.toFixed(2);}});
note("真值是 0",640,466,"y");
setCap("跑 100 轮之后的 V̂(s₁)：在策略 <b>2.62</b>（在往 0 走），离策略 <b>17.42</b>（在往反方向跑）。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:300,items:[
  {label:"特征",sub:"两边完全相同",state:"on"},
  {label:"α 与 γ",sub:"两边完全相同",state:"on"},
  {label:"数据分布",sub:"唯一的差别",state:"dead"}]});
note("真值就在可表示类里",640,420,"g");
setCap("<b>指名反驳</b>：不是特征也不是步长。<b>唯一变量是数据来自哪个策略。</b>");

clearScene();setBig(null);
setEq("$$\\lVert BV-BV'\\rVert_\\infty\\le\\gamma\\lVert V-V'\\rVert_\\infty$$","top");
note("L2 第八集证过",640,300,"g lg");
note("那怎么还会发散",640,360,"r lg");
setCap("Bellman 算子<b>确实</b>是 γ-压缩。这条定理没有被推翻。");

clearScene();setEq(null);
setBig("压缩映射不会发散","L2 已经证过了，用就是了");
setCap("定理没错，<b>但你跑的已经不是那个映射了</b>。");

clearScene();setBig(null);
setEq("$$V_{k+1}=\\Pi\\,B\\,V_k \\qquad \\Pi:\\ \\text{project onto } \\{x(\\cdot)^{\\top}w\\}$$","top");
note("B 是压缩",420,320,"g lg");
note("Π 可能是扩张",860,320,"r lg");
setCap("复合映射 <b>Π∘B</b>：压缩接一个可能扩张的投影，<b>结果未必还是压缩</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:300,items:[
  {label:"函数逼近",sub:"带来投影 Π",state:"dead"},
  {label:"自举",sub:"目标里含 w",state:"dead"},
  {label:"离策略",sub:"两个分布对不上",state:"dead"}]});
note("三个齐了才会炸",640,420,"r");
setCap("<b>致命三要素</b>：三个单独都没事，<b>凑齐才发散</b>。");

clearScene();setBig(null);setEq(null);
note("稳定",400,290,"g lg");
note("收敛到哪",880,290,"y lg");
note("两个问题，都要答",640,400,"r lg");
setCap("<b>指名反驳</b>：定理没错，你跑的不是那个映射。而且<b>稳定还不是终点</b>。");
